function build(api) {
  api.name('Sprout Stone');
  const C_BODY = 0xc67b30;
  const C_BODY_DARK = 0x5c3d2e;
  const C_SPROUT = 0x7ab648;
  const C_LEAF = 0x5a9e30;
  const C_LEAF_LIGHT = 0x8fcc52;

  api.group('body', 'body');
    // 轮廓块
    api.sphere({ r: 1.2, pos: [0, 1.2, 0], color: C_BODY });
    // 特征块
    api.box({ w: 2.4, h: 0.4, d: 2.4, pos: [0, 0.2, 0], color: C_BODY_DARK });
    // 色块面
    api.box({ w: 1.8, h: 0.08, d: 1.8, pos: [0, 1.85, 0], color: C_BODY_DARK });
    // 细节块
    api.poly({ r: 0.15, pos: [0.7, 0.45, 0.7], color: C_BODY_DARK });
    api.poly({ r: 0.12, pos: [-0.6, 0.4, 0.8], color: C_BODY_DARK });
    api.poly({ r: 0.1, pos: [0.5, 0.35, -0.7], color: C_BODY_DARK });
  api.endGroup();

  api.group('sprout', 'sprout');
    // 轮廓块
    api.cyl({ r: 0.12, h: 1.5, pos: [0, 3.15, 0], color: C_SPROUT });
    // 特征块
    api.cone({ r: 0.2, h: 0.3, pos: [0, 2.45, 0], along: '+Y', color: C_SPROUT });
    // 细节块
    api.tri({ a: [0, 3.9, 0], b: [0.6, 3.5, 0.3], c: [0.1, 3.3, 0.1], d: 0.06, color: C_LEAF });
    api.tri({ a: [0, 3.9, 0], b: [-0.5, 3.6, -0.2], c: [-0.1, 3.4, -0.1], d: 0.06, color: C_LEAF_LIGHT });
    api.tri({ a: [0, 3.7, 0], b: [0.3, 3.3, -0.4], c: [0.05, 3.2, -0.1], d: 0.06, color: C_LEAF });
  api.endGroup();
}
